import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Product — Delete","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-product-delete","title":"Delete a Catalog Product","description":"Deletes a catalog product. For configurable products, all variants cascade. No \\"refuse if in non-completed order\\" guard — mirrors Bagisto admin behaviour.","query":"curl -X DELETE \\"https://your-domain.com/api/admin/catalog/products/42\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","variables":"{}\\n","response":"<empty body — HTTP 204>\\n","commonErrors":[{"error":"Not Found (404)","cause":"Product not found","solution":"Verify the `{id}` exists"},{"error":"Forbidden (403)","cause":"Admin role lacks `catalog.products.delete`","solution":"Grant the permission to the admin role"}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/delete.md","filePath":"api/rest-api/admin/catalog/products/delete.md","lastUpdated":1787725411000}'),d={name:"api/rest-api/admin/catalog/products/delete.md"};function i(n,e,l,s,c,h){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="catalog-product-—-delete" tabindex="-1">Catalog Product — Delete <a class="header-anchor" href="#catalog-product-—-delete" aria-label="Permalink to &quot;Catalog Product — Delete&quot;">​</a></h1><p>Deletes a catalog product. Fires <code>catalog.product.delete.before</code> / <code>catalog.product.delete.after</code>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/{id}</code></td><td>DELETE</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>yes</td><td>Product ID.</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>204 No Content</code>, with an empty body — there is nothing to read back. Capture anything you need from <a href="/api/rest-api/admin/catalog/products/products-detail.html">Product Detail</a> before deleting.</p><h2 id="what-deletion-does" tabindex="-1">What Deletion Does <a class="header-anchor" href="#what-deletion-does" aria-label="Permalink to &quot;What Deletion Does&quot;">​</a></h2><ul><li><strong>Configurable variants cascade.</strong> Deleting the parent removes its variants; there is no separate call.</li><li><strong>Orders are unaffected.</strong> Order items keep their snapshot of the product, so historic orders still render after the product is gone.</li><li><strong>No in-order guard.</strong> A product that appears in open orders deletes without complaint, matching the admin panel. If you need referential integrity, enforce it before calling.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP</th><th>Detail</th></tr></thead><tbody><tr><td><code>401</code></td><td><code>Unauthenticated.</code></td></tr><tr><td><code>403</code></td><td><code>You do not have permission to manage products.</code> — token lacks <code>catalog.products.delete</code></td></tr><tr><td><code>404</code></td><td><code>Product not found.</code></td></tr></tbody></table>',12)]))}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
